#include <algorithm>
#include <array>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>
#include <set>
using namespace std;using ll=long long;using G=vector<int>;
void need(bool x,const char*s){if(!x)throw runtime_error(s);}bool arc(const G&a,int i,int j){return a[i]>>j&1;}
struct F{ll h=0,c=0;vector<ll>e,s,R;};
F literal(const G&a){int n=a.size();F f;f.e.resize(n);f.s.resize(n);f.R.resize(n);if(!n){f.h=1;return f;}vector<int>p(n);iota(p.begin(),p.end(),0);do{vector<int>bad(n);for(int i=1;i<n;i++)bad[i]=bad[i-1]+!arc(a,p[i-1],p[i]);if(!bad.back()){f.h++;f.s[p[0]]++;f.e[p.back()]++;if(p[0]==0&&n>=3&&arc(a,p.back(),0))f.c++;}for(int cut=0;cut<n;cut++)if((cut==0||bad[cut-1]==0)&&bad[n-1]==bad[cut])f.R[p[cut]]++;}while(next_permutation(p.begin(),p.end()));return f;}
G omit(const G&a,int r){G b(a.size()-1);for(int i=0;i<(int)a.size();i++)if(i!=r)for(int j=0;j<(int)a.size();j++)if(j!=r&&arc(a,i,j))b[i-(i>r)]|=1<<(j-(j>r));return b;}
G triangle(const G&a,int r){int n=a.size();G b(n+2);for(int i=0;i<n+2;i++)for(int j=i+1;j<n+2;j++){int u=i>=n?r:i,v=j>=n?r:j;bool f;if(u==r&&v==r){int I=i==r?0:i-n+1,J=j==r?0:j-n+1;f=(I+1)%3==J;}else f=arc(a,u,v);b[f?i:j]|=1<<(f?j:i);}return b;}
G append(const G&a,int root,int mask){G b=a;int n=a.size();b.push_back(0);for(int i=0;i<n;i++)if(mask&&i==root)b[n]|=1<<i;else b[i]|=1<<n;return b;}
ll gadget(int u){static vector<ll>cache(10000,-1);if(cache[u]>=0)return cache[u];vector<int>bits;for(int q=u-1;q;q/=2)bits.push_back(q%2);reverse(bits.begin(),bits.end());int r=bits.size();G S(r+1);for(int i=1;i<=r;i++){S[bits[i-1]?0:i]|=1<<(bits[i-1]?i:0);for(int j=i+1;j<=r;j++)S[i]|=1<<j;}ll count=0;for(int code=0;code<(1<<r);code++){vector<int>p;for(int i=0;i<r;i++)if(code>>i&1)p.push_back(i+1);p.push_back(0);for(int i=0;i<r;i++)if(!(code>>i&1))p.push_back(i+1);bool ok=1;for(int i=1;i<(int)p.size();i++)ok&=arc(S,p[i-1],p[i]);count+=ok;}return cache[u]=count;}
G build(vector<int>w){G a={2,0};for(int z:w){int n=a.size();a.push_back(0);for(int i=0;i<n;i++)if(i<2&&(z>>i&1))a[n]|=1<<i;else a[i]|=1<<n;}return a;}
vector<int> word(int u,int v){vector<int>b,w;for(int q=u-1;q;q/=2)b.push_back(q%2?1:3);reverse(b.begin(),b.end());w=b;w.push_back(2);w.push_back(3);for(int q=v-1;q;q/=2)w.push_back(q%2);return w;}
ll formula(int u,int v){ll D=gadget(u),p=u%2,t=v%2;return (D+3*u-p-2)*gadget(v)+(2*D+8*u-p-4)*v-u*(1+t)-p;}
// All ordinary vertices are in fixed transitive order. A Hamilton word splits
// them into three slots around the two ports. This is not endpoint subset DP.
ll slotpaths(const G&a){int r=a.size()-2;ll out=0,lim=1;for(int i=0;i<r;i++)lim*=3;for(ll code=0;code<lim;code++){vector<int>s[3];ll q=code;for(int i=2;i<(int)a.size();i++,q/=3)s[q%3].push_back(i);for(int order=0;order<2;order++){vector<int>p=s[0];p.push_back(order);p.insert(p.end(),s[1].begin(),s[1].end());p.push_back(1-order);p.insert(p.end(),s[2].begin(),s[2].end());bool ok=1;for(int i=1;i<(int)p.size();i++)ok&=arc(a,p[i-1],p[i]);out+=ok;}}return out;}
ll slotcycles(const G&a){int r=a.size()-2;ll out=0;for(int code=0;code<(1<<r);code++){vector<int>p={0};for(int i=0;i<r;i++)if(code>>i&1)p.push_back(i+2);p.push_back(1);for(int i=0;i<r;i++)if(!(code>>i&1))p.push_back(i+2);bool ok=arc(a,p.back(),0);for(int i=1;i<(int)p.size();i++)ok&=arc(a,p[i-1],p[i]);out+=ok;}return out;}
F pathwords(const G&a){int n=a.size(),N=1<<n;F f;f.e.resize(n);f.s.resize(n);f.R.resize(n);vector<vector<ll>>s(N,vector<ll>(n));vector<ll>h(N);h[0]=1;auto dfs=[&](auto&&self,int S,int first,int last)->void{s[S][first]++;h[S]++;if(S==N-1){f.h++;f.e[last]++;f.s[first]++;}for(int q=a[last]&~S;q;q&=q-1){int b=q&-q;self(self,S|b,first,__builtin_ctz((unsigned)b));}};for(int i=0;i<n;i++)dfs(dfs,1<<i,i,i);for(int S=1;S<N;S++)for(int r=0;r<n;r++)f.R[r]+=s[S][r]*h[(N-1)^S];return f;}
int main(){ll incidences=0,seams=0,starts=0,boundaries=0,cycles=0;for(int n=2;n<=5;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G a(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++){bool f=code>>k&1;a[f?i:j]|=1<<(f?j:i);}F old=literal(a);for(int r=0;r<n;r++){ll d=literal(omit(a,r)).h;for(int z=0;z<=1;z++){G b=append(a,r,z);F f=literal(b);need(f.h==(z?old.h-old.e[r]+old.R[r]:old.h),"seam H");need(f.e[r]==(z?d:0),"seam e");need(f.R[r]==(z?2*old.R[r]-d:2*old.R[r]),"seam R");need(literal(omit(b,r)).h==d&&f.s[r]==old.s[r],"seam d/s");if(z)need(f.c==old.s[r],"seam cycles");seams++;}if(__builtin_popcount((unsigned)a[r])!=1)continue;int b=__builtin_ctz((unsigned)a[r]);G out=triangle(a,r);F f=literal(out);need(f.h==3*old.h+3*old.R[b]-3*old.e[b],"triangle H");need(f.e[r]==old.e[r]+old.R[b]-old.e[b],"triangle e");need(f.R[r]==2*old.h+old.R[r]+4*old.R[b]-2*old.e[b],"triangle R");need(literal(omit(out,r)).h==old.h+old.R[b]-old.e[b],"triangle deletion");if(n>=3){need(f.s[r]==3*old.s[r],"triangle start");starts++;}else{need(f.s[r]==1&&old.s[r]==1,"size-two start boundary");boundaries++;}if(old.c){need(f.c==3*old.c,"triangle cycle law");cycles++;}incidences++;}}
// Independent module-slot assignment: assign each labelled triangle vertex a slot,
// then enumerate each slot's possible internal order, rather than concatenation cuts.
array<int,4>part{};G tri={2,4,1};for(int code=0;code<27;code++){vector<int>s[3];int q=code;for(int i=0;i<3;i++,q/=3)s[q%3].push_back(i);sort(s[0].begin(),s[0].end());do{sort(s[1].begin(),s[1].end());do{sort(s[2].begin(),s[2].end());do{bool ok=1;for(auto&t:s)for(int i=1;i<(int)t.size();i++)ok&=arc(tri,t[i-1],t[i]);if(!ok)continue;if(!s[1].empty()&&s[1][0]==0){part[0]++;if(s[2].empty())part[1]++;}if(!s[0].empty()&&!s[2].empty()&&s[2][0]==0){part[2]++;if(s[1].empty())part[3]++;}}while(next_permutation(s[2].begin(),s[2].end()));}while(next_permutation(s[1].begin(),s[1].end()));}while(next_permutation(s[0].begin(),s[0].end()));}need(part==array<int,4>{7,3,4,2},"module slots");
int physical=0;for(int u=2;u<=20;u++){G seed=build(word(u,1));F f=pathwords(seed);ll D=gadget(u),p=u%2;need(f.h==3*D+9*u-3*p-6&&f.e[0]==D+2*u-p-2&&f.R[0]==3*D+11*u-2*p-6,"gate seed exact profiles");need(pathwords(omit(seed,0)).h==D+3*u-p-2&&f.s[0]==3,"gate seed d/s");for(int v=1;v<=20;v++){G a=build(word(u,v));need(slotpaths(a)==formula(u,v),"family independent slots H");need(slotcycles(a)==3,"family independent slots C");for(int i=2;i<(int)a.size();i++)for(int j=i+1;j<(int)a.size();j++)need(arc(a,i,j),"FVS at most two");physical++;}}
for(auto x:vector<array<int,3>>{{4,2,67},{8,7,533},{6,31,1861}}){G a=build(word(x[0],x[1]));need(slotpaths(a)==x[2]&&slotcycles(a)==3,"examples");cout<<"EXAMPLE "<<x[0]<<" "<<x[1]<<" H "<<x[2]<<" ROWS";for(auto row:a)cout<<" "<<row;cout<<"\n";}
for(int u=1;u<=714;u++){ll expected=u==1?1:u%2==0?gadget(u/2):gadget((u+1)/2)+(u+1)/2-((u+1)/2)%2;need(gadget(u)==expected,"physical gadget recurrence");}set<ll>image;ll tested=0;for(int u=2;u<=714;u++)for(int v=1;v<=714/u;v++){ll H=formula(u,v);need(H>=7LL*u*v+1,"inverse bound");if(H<=5001)image.insert(H);tested++;}need(image.size()==1581&&!image.count(821),"image exact inverse");for(auto x:image)cerr<<x<<"\n";
cout<<"PASS incidences "<<incidences<<" start_laws "<<starts<<" size_two_boundaries "<<boundaries<<" strong_cycle_laws "<<cycles<<" seam_controls "<<seams<<" family_graphs "<<physical<<" module_partitions 7 3 4 2 physical_gadget_values 714 inverse_pairs "<<tested<<" image_size "<<image.size()<<"\n";
}
